import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. Double Border / Accent Ring for high contrast (Machined look)
  const borderOuterGeom = new PlaneGeometry(2.44, 3.24);
  const borderOuterMat = new MeshBasicNodeMaterial();
  borderOuterMat.colorNode = vec3(new Color(colors.accent));
  const borderOuter = new Mesh(borderOuterGeom, borderOuterMat);
  borderOuter.position.z = -0.02;
  group.add(borderOuter);

  const borderInnerGeom = new PlaneGeometry(2.4, 3.2);
  const borderInnerMat = new MeshBasicNodeMaterial();
  borderInnerMat.colorNode = vec3(new Color(colors.surface));
  const borderInner = new Mesh(borderInnerGeom, borderInnerMat);
  borderInner.position.z = -0.01;
  group.add(borderInner);

  // 2. Card Subject Base
  const baseGeom = new PlaneGeometry(2.34, 3.14);
  const baseMat = new MeshBasicNodeMaterial();
  const gradBottom = vec3(new Color(colors.surface));
  const gradTop = vec3(new Color(colors.ink));
  baseMat.colorNode = mix(gradBottom, gradTop, uv().y);
  const base = new Mesh(baseGeom, baseMat);
  group.add(base);

  // 3. Subject Image Plate
  const imageGeom = new PlaneGeometry(2.1, 2.1);
  const imageMat = new MeshBasicNodeMaterial({ transparent: true });
  // Start dark grey and assign loaded texture
  imageMat.colorNode = vec3(new Color('#121217'));
  const imageMesh = new Mesh(imageGeom, imageMat);
  imageMesh.position.set(0, 0.25, 0.01);
  group.add(imageMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        imageMat.map = tex;
        imageMat.colorNode = null;
        imageMat.needsUpdate = true;
      })
      .catch((err) => console.warn('Failed loading image asset:', err));
  }

  // 4. Subtle Machined Mono Label
  const label = ctx.fontAtlas.createText('SERIES_A // N°01', {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center'
  });
  label.position.set(0, -1.15, 0.02);
  group.add(label);

  const accentTickGeom = new PlaneGeometry(0.12, 0.02);
  const accentTickMat = new MeshBasicNodeMaterial();
  accentTickMat.colorNode = vec3(new Color(colors.accent));
  const accentTick = new Mesh(accentTickGeom, accentTickMat);
  accentTick.position.set(0, -0.95, 0.02);
  group.add(accentTick);

  // 5. Entrance Motion
  const tl = gsap.timeline();
  // Lift into view with weighted-settle signature
  const targetY = config.scenePosition?.[1] ?? -0.3;
  group.position.set(
    config.scenePosition?.[0] ?? -3.2,
    targetY - 0.4,
    config.scenePosition?.[2] ?? 0
  );

  tl.to(group.position, {
    y: targetY,
    duration: 0.9,
    ease: 'power4.out'
  });

  // Cleanup reference
  group.userData = {
    cleanup() {
      tl.kill();
      borderOuterGeom.dispose();
      borderOuterMat.dispose();
      borderInnerGeom.dispose();
      borderInnerMat.dispose();
      baseGeom.dispose();
      baseMat.dispose();
      imageGeom.dispose();
      imageMat.dispose();
      accentTickGeom.dispose();
      accentTickMat.dispose();
    }
  };

  return group;
}
